INSERT INTO feature VALUES('std-io','modules','The standard streams','packages','implemented','uncommon','mainstream languages','`std.io`''s `print` and `eprint` write one line to standard output and standard error, and `read_line` reads one from standard input with its newline, the empty string at its end, each through the console''s root capability, which `std.authority`''s `console` opens from the authority `main` is handed; a program reaches the streams through a capability it was given and never through the ambient interfaces, each stream a host interface of its own.','surface-dispatcher surface-driver core-term','library/std/src/io.gandr corpus/model/effects/hello.gandr corpus/model/console/answer.gandr crates/surface-driver/tests/cli.rs::a_program_reads_and_answers_on_the_standard_streams_2970','corpus/ledger/features/std-io.gandr',NULL);
